from opentrons import protocol_api

# ----------------------------------------------------------------------------
# OT-2 Protocol Skeleton with Placeholders (API v2.19)
# This script is designed to be templatable. All core deck loading and pipetting
# actions are demonstrated, but many values are provided as [[PLACEHOLDER]] tokens
# to be substituted by a templating system before running on real hardware.
# ----------------------------------------------------------------------------

# Header and metadata (required by OT-2 API)
metadata = {
    'protocolName': '[protocol name by user]',
    'author': '[user name]',
    'description': "[what is the protocol about]"
}
requirements = {"robotType": "OT-2", "apiLevel": "2.19"}

# Placeholder tokens (to be substituted)
REPLICATES = '[[REPLICATES]]'                 
TOTAL_VOLUME = '[[TOTAL_VOLUME]]'               
SALT_CONCENTRATIONS = '[[SALT_CONCENTRATIONS]]'        
LIGAND_CONCENTRATIONS = '[[LIGAND_CONCENTRATIONS]]'    
SALT_STOCK_CONCENTRATION = '[[SALT_STOCK_CONCENTRATION]]'  
LIGAND_STOCK_CONCENTRATION = '[[LIGAND_STOCK_CONCENTRATION]]'  
NUMBER_OF_SALT_CONCENTRATIONS = '[[NUMBER_OF_SALT_CONCENTRATIONS]]'  
NUMBER_OF_LIGAND_CONCENTRATIONS = '[[NUMBER_OF_LIGAND_CONCENTRATIONS]]'  

# Helper parsing functions to allow simulation with placeholders

def _decode_int(v, default=1):
    try:
        if isinstance(v, int):
            return v
        if isinstance(v, str) and v.strip().startswith('[['):
            # placeholder detected
            protocol_api.ProtocolContext.comment
            return default
        return int(v)
    except Exception:
        return default


def _decode_float(v, default=1.0):
    try:
        if isinstance(v, (int, float)):
            return float(v)
        if isinstance(v, str) and v.strip().startswith('[['):
            return default
        return float(v)
    except Exception:
        return default


def _decode_list(v, default=None):
    if isinstance(v, list):
        return v
    if isinstance(v, str) and v.strip().startswith('[['):
        return default if default is not None else []
    if isinstance(v, str):
        s = v.strip()
        if s == '':
            return []
        parts = [p.strip() for p in s.split(';') if p.strip()]
        out = []
        for p in parts:
            try:
                if '.' in p or 'e' in p or 'E' in p:
                    out.append(float(p))
                else:
                    out.append(int(p))
            except Exception:
                out.append(p)
        return out
    return default if default is not None else []


def _parse_ip(v, default=1):
    if isinstance(v, int):
        return v
    if isinstance(v, str) and v.strip().startswith('[['):
        return default
    try:
        return int(v)
    except Exception:
        return default


def _parse_fp(v, default=1.0):
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str) and v.strip().startswith('[['):
        return default
    try:
        return float(v)
    except Exception:
        return default


def _parse_script_placeholder(v, default=None):
    if isinstance(v, str) and v.strip().startswith('[[') and v.strip().endswith(']]'):
        return default
    return v


def run(protocol: protocol_api.ProtocolContext):
    # 1) Deck setup per user specification
    # Slot 1: Cytiva custom labware (may be missing in simulation)
    try:
        plate = protocol.load_labware('cytiva_96_filterwellplate_1ml', 1)
        protocol.comment('Loaded custom labware: cytiva_96_filterwellplate_1ml in slot 1')
    except Exception:
        protocol.comment('Custom labware cytiva_96_filterwellplate_1ml not available; using Nest alternative for simulation')
        plate = protocol.load_labware('nest_96_wellplate_200ul_flat', 1)

    # Slot 4,7,10: Tip racks
    tiprack_right = protocol.load_labware('opentrons_96_tiprack_300ul', 4)
    tiprack_left_a = protocol.load_labware('opentrons_96_tiprack_300ul', 7)
    tiprack_left_b = protocol.load_labware('opentrons_96_tiprack_300ul', 10)

    # Slot 3: Reservoir 4 empty (we still load it for completeness)
    reservoir_4 = protocol.load_labware('nest_12_reservoir_15ml', 3)
    # Slot 6: Reservoir 3 empty
    reservoir_3 = protocol.load_labware('nest_12_reservoir_15ml', 6)
    # Slot 8: Reservoir 2
    reservoir_2 = protocol.load_labware('nest_12_reservoir_15ml', 8)
    # Slot 9: Reservoir 1
    reservoir_1 = protocol.load_labware('nest_12_reservoir_15ml', 9)
    # Slot 5: Reservoir 0
    reservoir_0 = protocol.load_labware('nest_12_reservoir_15ml', 5)

    # Slot 11: Mixing plate
    mixing_plate = protocol.load_labware('nest_96_wellplate_2ml_deep', 11)

    # Pipettes
    p300_single = protocol.load_instrument('p300_single_gen2', mount='right', tip_racks=[tiprack_right])
    p300_multi = protocol.load_instrument('p300_multi_gen2', mount='left', tip_racks=[tiprack_left_a, tiprack_left_b])

    # 2) Placeholders definitions (as strings to remain templatable)
    REPLICATES = '[[REPLICATES]]'
    TOTAL_VOLUME = '[[TOTAL_VOLUME]]'
    SALT_CONCENTRATIONS = '[[SALT_CONCENTRATIONS]]'
    LIGAND_CONCENTRATIONS = '[[LIGAND_CONCENTRATIONS]]'
    SALT_STOCK_CONCENTRATION = '[[SALT_STOCK_CONCENTRATION]]'
    LIGAND_STOCK_CONCENTRATION = '[[LIGAND_STOCK_CONCENTRATION]]'
    NUMBER_OF_SALT_CONCENTRATIONS = '[[NUMBER_OF_SALT_CONCENTRATIONS]]'
    NUMBER_OF_LIGAND_CONCENTRATIONS = '[[NUMBER_OF_LIGAND_CONCENTRATIONS]]'

    # Basic parsing helpers for unused placeholders in simulation
    def _decode_int(v, default=1):
        try:
            if isinstance(v, int):
                return v
            if isinstance(v, str) and v.strip().startswith('[['):
                protocol.comment('PLACEHOLDER detected; using default {}'.format(default))
                return default
            return int(v)
        except Exception:
            return default

    def _decode_float(v, default=1.0):
        try:
            if isinstance(v, (int, float)):
                return float(v)
            if isinstance(v, str) and v.strip().startswith('[['):
                protocol.comment('PLACEHOLDER detected; using default {}'.format(default))
                return default
            return float(v)
        except Exception:
            return default

    def _decode_list(v, default=None):
        if isinstance(v, list):
            return v
        if isinstance(v, str) and v.strip().startswith('[['):
            protocol.comment('PLACEHOLDER detected; using default list')
            return default if default is not None else []
        if isinstance(v, str):
            items = [it for it in [s.strip() for s in v.split(';')] if it]
            return items if items else []
        return default if default is not None else []

    REPLICATES_INT = _decode_int(REPLICATES, default=1)
    TOTAL_VOLUME_F = _decode_float(TOTAL_VOLUME, default=10.0)
    SALT_CONCS = _decode_list(SALT_CONCENTRATIONS, default=[])
    LIG_CONCS = _decode_list(LIGAND_CONCENTRATIONS, default=[])
    SALT_COUNT = _decode_int(NUMBER_OF_SALT_CONCENTRATIONS, default=len(SALT_CONCS))
    LIG_COUNT = _decode_int(NUMBER_OF_LIGAND_CONCENTRATIONS, default=len(LIG_CONCS))

    # 3) Minimal active protocol steps that are safe in simulation
    # Demo: a tiny transfer to show API usage and log steps via protocol.comment
    # We use a safe 1 µL transfer from Reservoir 0 to the first well in Plate if placeholders are not substituted
    try:
        if REPLICATES_INT > 0 and len(plate_wells := plate.wells()) > 0:
            dest_well = plate_wells[0]
            if reservoir_0.wells():
                protocol.comment('Demo: transferring 1 µL from Reservoir 0 WELL 1 to first destination well to validate protocol syntax')
                p300_single.transfer(1.0, reservoir_0.wells()[0], dest_well, new_tip='never')
    except Exception as e:
        protocol.comment('Warning: Demo transfer could not be executed: {}'.format(str(e)))

# End of protocol skeleton

